#!/usr/bin/env python3
"""rc.1 fix pass, crosswalk data (D-DATA; ADR-0032; DATA_FIX_BRIEF §8, §12). Idempotent; untouched cells stay byte-identical.

  M9   One NoTermFound convention for every set (vocab/mapping_predicates.yaml#no_match_convention): a row whose object
       is sssom:NoTermFound and whose predicate is a SKOS predicate carries predicate_modifier Not ("no closeMatch was
       found"), so no NoTermFound row asserts a positive predicate. The column is added where a set lacked it.
       X2: review_status two-coder-agreed-target -> two-llm-coders-agreed-target; the set metadata records kappa and
       the honest coverage numbers (rows, rows with an O*NET object, agreed, agreed at closeMatch or better).
  m14  `held_variants=...` is dropped from `other` (X3, X4); set metadata reworded so no held item or reason is named
       (D-BUILD REQUESTS_FOR_DATA R3). X1 is generated by scripts/migrate_v1.py (justification and metadata there).
The pipelines that generate these sets (pipelines/crosswalks/sssomlib.py, x3_soc.py, x4_opm_series.py,
x8_x11_private.py, pipelines/x2/merge_x2.py) apply the same rules on their next run.
Run: python3 -I docs/build/rc1-fix/fix_crosswalks.py   Licence: Apache-2.0.
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import rc1lib as R  # noqa: E402

L = R.L
XW = L.DATA_V2 / "crosswalks"
NO_TERM = "sssom:NoTermFound"
SKOS = {"skos:exactMatch", "skos:closeMatch", "skos:broadMatch", "skos:narrowMatch", "skos:relatedMatch"}
GOOD = {"skos:exactMatch", "skos:closeMatch"}
REWORD = {
    "onet-soc/2019.sssom.yml": [("Tribal role variants are held (ADR-0007 §D) and not mapped.", "Held variants are not mapped (ADR-0007 §D).")],
    "soc/2018.sssom.yml": [("Tribal role variants are held (ADR-0007 §D) and not mapped.", "Held variants are not mapped (ADR-0007 §D).")],
    "opm-series-competency/2026-10-23.sssom.yml": [("Rows whose v1 competency is held for Tribal review, retired or moved to tools are omitted",
                                                     "Rows whose v1 competency is held, retired or moved to tools are omitted")],
}
NOTERM_DESC = ("skos:closeMatch sssom:NoTermFound = no SOC occupation adequately covers the role",
               "skos:closeMatch with predicate_modifier Not and object sssom:NoTermFound = no SOC occupation adequately "
               "covers the role (no NoTermFound row asserts a positive predicate; ADR-0032)")


def fix_tsv(path: Path) -> dict:
    lines = path.read_text(encoding="utf-8").split("\n")
    head_i = next(i for i, ln in enumerate(lines) if ln and not ln.startswith("#"))
    header = lines[head_i].split("\t")
    body = [ln.split("\t") for ln in lines[head_i + 1:] if ln]
    stats = {"modifier": 0, "held": 0, "status": 0, "column": 0}
    ip, io, ioth = header.index("predicate_id"), header.index("object_id"), header.index("other")
    needs = any(c[io] == NO_TERM and c[ip] in SKOS for c in body)
    if "predicate_modifier" not in header and needs:    # add the column only where a row needs it (pipelines drop empty ones)
        header.insert(ip + 1, "predicate_modifier")
        body = [c[:ip + 1] + [""] + c[ip + 1:] for c in body]
        io, ioth = header.index("object_id"), header.index("other")
        stats["column"] = 1
    im = header.index("predicate_modifier") if "predicate_modifier" in header else None
    for c in body:
        if im is not None and c[io] == NO_TERM and c[ip] in SKOS and c[im] != "Not":
            c[im] = "Not"
            stats["modifier"] += 1
        parts = [x for x in c[ioth].split(";") if x]
        keep = [x for x in parts if not x.startswith("held_variants=")]
        stats["held"] += len(keep) != len(parts)
        renamed = ["review_status=two-llm-coders-agreed-target" if x == "review_status=two-coder-agreed-target" else x for x in keep]
        stats["status"] += renamed != keep
        c[ioth] = ";".join(renamed)
    text = "\n".join(lines[:head_i] + ["\t".join(header)] + ["\t".join(c) for c in body]) + "\n"
    if text != path.read_text(encoding="utf-8"):
        path.write_text(text, encoding="utf-8")
        R.LOG.append(f"{path.relative_to(L.ROOT)}: {stats}")
    return stats


def x2_numbers(path: Path) -> dict:
    lines = [ln for ln in path.read_text(encoding="utf-8").splitlines() if ln and not ln.startswith("#")]
    header = lines[0].split("\t")
    rows = [dict(zip(header, ln.split("\t"))) for ln in lines[1:]]
    other = lambda r: dict(p.split("=", 1) for p in r["other"].split(";") if "=" in p)  # noqa: E731
    real = [r for r in rows if r["object_id"] != NO_TERM]
    agreed = [r for r in real if other(r).get("review_status") == "two-llm-coders-agreed-target"]
    return {"rows": len(rows), "with_onet_object": len(real), "agreed": len(agreed),
            "agreed_close_or_better": sum(1 for r in agreed if r["predicate_id"] in GOOD and r.get("predicate_modifier") != "Not"),
            "no_term_found": len(rows) - len(real)}


def fix_x2_meta(n: dict):
    p = XW / "onet-task" / "27.2.sssom.yml"
    k = json.loads((L.ROOT / "pipelines" / "x2" / "work" / "x2_kappa.json").read_text(encoding="utf-8"))
    kap, ci = k["kappa_match_type"], k["kappa_match_type_ci95"]

    def fn(md):
        desc = md["mapping_set_description"]
        desc = desc.replace("review_status: single-coder-candidate | two-coder-agreed-target | needs-adjudication",
                            "review_status: single-coder-candidate | two-llm-coders-agreed-target | needs-adjudication")
        marker = " Honest coverage (ADR-0032; review M9):"
        if marker in desc:
            desc = desc[:desc.index(marker)]
        desc += (f"{marker} rows {n['rows']}; with an O*NET object {n['with_onet_object']}; agreed by both LLM coders "
                 f"{n['agreed']}; agreed at closeMatch or better {n['agreed_close_or_better']}; NoTermFound "
                 f"{n['no_term_found']} (predicate_modifier Not). Coder agreement on match type kappa {kap} (95% CI "
                 f"{ci[0]}-{ci[1]}), below the ADR-0022 target 0.6: the X2 gate fails. Not for exposure joins.")
        md["mapping_set_description"] = desc
        md["other"] = (f"kappa_match_type={kap};kappa_ci95={ci[0]}-{ci[1]};target_kappa=0.6;kappa_source=pipelines/x2/work/"
                       f"x2_kappa.json;coders=two LLM coders (LLM-vs-LLM agreement, not human inter-coder reliability);"
                       f"rows={n['rows']};with_onet_object={n['with_onet_object']};agreed={n['agreed']};"
                       f"agreed_close_or_better={n['agreed_close_or_better']};gate=fail")
        return md
    R.edit_yaml(p, fn)


def fix_meta_text():
    for rel, subs in REWORD.items():
        p = XW / rel

        def fn(md, subs=subs):
            for k, v in list(md.items()):
                if isinstance(v, str):
                    for a, b in subs + [NOTERM_DESC]:
                        v = v.replace(a, b)
                    md[k] = v
            return md
        R.edit_yaml(p, fn)
    p = XW / "emst-public-private" / "0.1.0.sssom.yml"

    def pp(md):
        for k, v in list(md.items()):
            if isinstance(v, str):
                md[k] = re.sub(r"TR-14 touches [^.;]*?(?:and )?is left for TN review", "TR-14 is left for review", v)
        return md
    R.edit_yaml(p, pp)


def main():
    totals = {}
    for tsv in sorted(XW.rglob("*.sssom.tsv")):
        if tsv.parent.name == "emst-v1":
            continue                      # generated by scripts/migrate_v1.py
        totals[str(tsv.relative_to(XW))] = fix_tsv(tsv)
    n = x2_numbers(XW / "onet-task" / "27.2.sssom.tsv")
    fix_x2_meta(n)
    fix_meta_text()
    print("X2:", n)
    print("NoTermFound rows given predicate_modifier Not:", sum(s["modifier"] for s in totals.values()),
          "| rows with held_variants dropped:", sum(s["held"] for s in totals.values()))
    R.summary("fix_crosswalks")


if __name__ == "__main__":
    main()
